{"command": "cd /workspace && cat > py/fxtest.py <<'PY'
import numpy as np, struct, json, subprocess, sys
sys.path.insert(0,'/workspace/py')

N=1000
t=np.arange(N)
x=np.sin(2*np.pi*10*t/N)*0.9
a8=np.clip(np.round(x*110),-128,127).astype(np.int32)
RAW8=np.clip(np.diff(a8,prepend=0),-128,127).astype(np.int8).tobytes()
a16=np.round(x*30000).astype(np.int32)
RAW16=np.diff(a16,prepend=0).astype('<i2').tobytes()

def cell(c,n=None,i=None,v=None,fx=None,p=None):
    out=bytearray(); m=0x80
    if n: m|=0x01; out.append(n)
    if i: m|=0x02; out.append(i)
    if v is not None: m|=0x04; out.append(v)
    if fx is not None or p is not None: m|=0x08|0x10; out.append(fx or 0); out.append(p or 0)
    return bytes([m])+bytes(out)

def build(path, rows_cells, channels=1, note_rows=1, speed=6, bpm=125, bits8=True):
    raw = RAW8 if bits8 else RAW16
    typ = 0x01 if bits8 else 0x11
    hdr=struct.pack('<IIIBbBBbB22s', len(raw), 0, N, 64,0,typ,128,0,0,b'FX'.ljust(22,b'\0'))
    out=bytearray()
    out+=b'Extended Module: '+b'FX'.ljust(20,b'\0')+bytes([0x1A])+b'FastTracker v2.00   '
    out+=struct.pack('<HI',0x0104,276)
    out+=struct.pack('<HHHHHHHH',1,0,channels,1,1,1,speed,bpm)+bytes(256)
    cells=bytearray()
    for r in range(64):
        for c in range(channels):
            cl=rows_cells.get((r,c))
            cells += cl if cl else bytes([0x80])
    out+=struct.pack('<IBHH',9,0,64,len(cells))+bytes(cells)
    blk=bytearray(); blk+=b'INS'.ljust(22,b'\0')+bytes([0])+struct.pack('<H',1)+struct.pack('<I',40)
    blk+=hdr+bytes(263-33-40)
    out+=struct.pack('<I',263)+bytes(blk)+hdr+raw
    open(path,'wb').write(bytes(out))

tests={}
# 1 baseline
tests['base']={(0,0):cell(0,49,1,0x40)}
# 2 volume column steps
c2={}
for r,v in ((0,0x40),(16,0x20),(32,0x10),(48,0x08)):
    c2[(r,0)]=cell(0,49,1,v)
tests['volcol']=c2
# 3 volume slide down A04
tests['vsldown']={(0,0):cell(0,49,1,0x40,0x0A,0x04)}
# 4 arpeggio 037
tests['arp']={(0,0):cell(0,49,1,0x40,0x00,0x37)}
# 5 vibrato 0x84
tests['vib']={(0,0):cell(0,49,1,0x40,0x04,0x84)}
# 6 set volume C20 at row 16
tests['setvol']={(0,0):cell(0,49,1,0x40),(16,0):cell(None,None,None,0x00,0x0C,0x20)}
# 7 note off at row 16
tests['noteoff']={(0,0):cell(0,49,1,0x40),(16,0):cell(97)}
# 8 note cut EC3 at row 16
tests['notecut']={(0,0):cell(0,49,1,0x40),(16,0):cell(None,None,None,None,0x0E,0xC3)}
# 9 porta down 2 0x0208
tests['porta']={(0,0):cell(0,49,1,0x40),(4,0):cell(None,None,None,None,0x02,0x20)}
# 10 set panning 8855 at row 0
tests['pan']={(0,0):cell(0,49,1,0x40,0x08,0x55)}
# 11 tempo F at row 16: FA0 = 160bpm
tests['tempo']={(0,0):cell(0,49,1,0x40),(16,0):cell(None,None,None,None,0x0F,0xA0)}
# 12 volume column slide down (0x70-0x7f are fine slide down in FT2: 0x71..0x7f = vol slide down)
tests['vcolslide']={(0,0):cell(0,49,1,0x70|0x07)}
# 13 16-bit sample baseline
tests['base16']={(0,0):cell(0,49,1,0x40),'bits8':False}

cmds=[]; names=[]
for name,cells in tests.items():
    bits8=cells.pop('bits8',True) if isinstance(cells,dict) else True
    p=f'/workspace/work/fx_{name}.xm'
    build(p, cells, bits8=bits8)
    names.append((name,bits8))
    cmds += [{"name":"module_load","arguments":{"path":p}},
             {"name":"module_render","arguments":{"path":f"/workspace/work/fx_{name}.wav","rate":44100,"bits":16,"loops":1}}]
json.dump(cmds,open('work/cmfx.json','w'))
r=subprocess.run(['ft2','batch','work/cmfx.json'],capture_output=True,text=True)
print('ok', r.stdout.count('"samples"'))
json.dump(names,open('work/fxnames.json','w'))
