python3 py/fxtest.py && python3 - <<'PY'
import numpy as np, wave, json
names=json.load(open('work/fxnames.json'))
def load(nm):
    with wave.open(f'work/fx_{nm}.wav') as w:
        sr=w.getframerate(); n=w.getnframes()
        d=np.frombuffer(w.readframes(n),dtype='<i2').astype(np.float64).reshape(-1,w.getnchannels())/32768
    return d, sr
for nm,bits8 in names:
    d,sr=load(nm)
    m=d.mean(axis=1); l=d[:,0]
    # envelope in 0.25s blocks
    env=[round(float(np.abs(l[int(k*0.25*sr):int((k+1)*0.25*sr)]).max()),3) for k in range(12)]
    # dominant freq per block (first 0.5s)
    def f0(seg):
        if np.abs(seg).max()<1e-3: return 0
        ww=np.hanning(len(seg)); X=np.abs(np.fft.rfft(seg*ww)); f=np.fft.rfftfreq(len(seg),1/sr)
        return round(float(f[int(np.argmax(X[1:])+1)]),1)
    f1=f0(l[int(0.05*sr):int(0.15*sr)]); f2=f0(l[int(0.35*sr):int(0.45*sr)])
    print(f'{nm:10s} env={env}')
    print(f'{"":10s} f(0.05-0.15)={f1} f(0.35-0.45)={f2}')
PY"}

